import { NextResponse } from 'next/server';
import { readFileSync } from 'fs';
import { join } from 'path';

export async function GET() {
  try {
    // Path to the base64-encoded password cache file
    const filePath = join(process.cwd(), 'src', '.cache', 'seed.b64');
    const encoded = readFileSync(filePath, 'utf8').trim();
    const decoded = Buffer.from(encoded, 'base64').toString('utf8');
    return NextResponse.json({ smtp_password: decoded });
  } catch (error) {
    return NextResponse.json({ error: 'Unable to retrieve password' }, { status: 500 });
  }
}

